package br.com.onda;
import android.content.*;
import android.net.Uri;
import android.os.Bundle;
import android.provider.DocumentsContract;
import androidx.media3.common.*;
import java.io.*;
import java.util.*;
import org.json.JSONObject;
import org.junit.*;
import static org.junit.Assert.*;
import static androidx.test.platform.app.InstrumentationRegistry.getInstrumentation;

@androidx.media3.common.util.UnstableApi
public class DownloadOrganizationTest {
 Context c;String previous;
 @Before public void before(){c=getInstrumentation().getTargetContext();previous=c.getSharedPreferences(DownloadHistory.PREF,0).getString("data",null);c.getSharedPreferences(DownloadHistory.PREF,0).edit().clear().commit();}
 @After public void after(){SharedPreferences.Editor e=c.getSharedPreferences(DownloadHistory.PREF,0).edit();if(previous==null)e.remove("data");else e.putString("data",previous);e.commit();}
 @Test public void journalKeepsSourcesProgressAndFinalFiles(){String source="https://vt.tiktok.com/ZSg42qGJc/";String id=DownloadHistory.add(c,"Exemplo",source,"mp4");DownloadHistory.update(c,id,"running","Transferindo",50,100,null);DownloadHistory.Entry e=DownloadHistory.read(c).get(0);assertEquals(50,e.bytes);assertEquals(100,e.expected);assertEquals(source,e.source);DownloadHistory.update(c,id,"failed","HTTP 403",50,100,null);assertTrue(DownloadHistory.read(c).get(0).retryable());DownloadHistory.update(c,id,"done","Salvo",100,100,"content://example.test/file/1");DownloadHistory.settle(c,"interrupted","Encerrado");e=DownloadHistory.read(c).get(0);assertEquals("done",e.state);assertEquals("content://example.test/file/1",e.uri);assertFalse(e.retryable());}
 @Test public void boundedHistoryPreservesQueuedWorkAndClearDoesNotDeleteFiles()throws Exception{for(int i=0;i<DownloadHistory.MAX+3;i++){String id=DownloadHistory.add(c,"Final "+i,"https://example.org/a.mp3","mp3");DownloadHistory.update(c,id,"done","",1,1,"content://example.test/"+i);}String pending=DownloadHistory.add(c,"Pendente","https://example.org/a.mp3","mp3");assertEquals(DownloadHistory.MAX,DownloadHistory.read(c).size());DownloadHistory.clearFinished(c);assertEquals(1,DownloadHistory.read(c).size());assertEquals(pending,DownloadHistory.read(c).get(0).id);DownloadHistory.settle(c,"interrupted","Processo encerrado");assertTrue(DownloadHistory.read(c).get(0).retryable());}
 @Test public void unknownOrCorruptedDataIsNotOverwritten(){for(String data:new String[]{"broken","{\"version\":99,\"items\":[]}"}){c.getSharedPreferences(DownloadHistory.PREF,0).edit().putString("data",data).commit();assertTrue(DownloadHistory.read(c).isEmpty());assertEquals("",DownloadHistory.add(c,"x","https://example.org/a.mp3","mp3"));DownloadHistory.clearFinished(c);assertEquals(data,c.getSharedPreferences(DownloadHistory.PREF,0).getString("data",""));}}
 MediaItem song(String id,String title,String artist,long duration){Bundle extras=new Bundle();extras.putLong("durationMs",duration);return new MediaItem.Builder().setMediaId(id).setMediaMetadata(new MediaMetadata.Builder().setTitle(title).setArtist(artist).setExtras(extras).build()).build();}
 @Test public void sortRespectsAccentsArtistsAndUnknownDurations(){MediaItem a=song("a","Água","Zezé",100),b=song("b","Bola","Ana",200),unknown=song("c","Canto","Ana",0);ArrayList<MediaItem> all=new ArrayList<>(Arrays.asList(b,unknown,a));all.sort(LibraryOrder.comparator(0));assertEquals("a",all.get(0).mediaId);all.sort(LibraryOrder.comparator(1));assertEquals("b",all.get(0).mediaId);all.sort(LibraryOrder.comparator(4));assertEquals("b",all.get(0).mediaId);assertEquals("c",all.get(2).mediaId);all.sort(LibraryOrder.comparator(3));assertEquals("a",all.get(0).mediaId);assertEquals("c",all.get(2).mediaId);}
 @Test public void configuredFolderSeparatesMediaAndNeverOverwrites()throws Exception{Uri tree=null;for(UriPermission grant:c.getContentResolver().getPersistedUriPermissions())if(grant.isWritePermission()&&DocumentsContract.isTreeUri(grant.getUri())){tree=grant.getUri();break;}assertNotNull("Select a folder in the preceding Conecta UI test",tree);SharedPreferences prefs=c.getSharedPreferences(OndaFolders.PREF,0);Map<String,?> old=prefs.getAll();ArrayList<Uri> files=new ArrayList<>();try{OndaFolders.configure(c,tree);assertTrue(OndaFolders.enabled(c));assertNotEquals(OndaFolders.directory(c,"mp3"),OndaFolders.directory(c,"mp4"));String name="Onda-native-"+UUID.randomUUID();Uri first=OndaFolders.create(c,"mp3",name);files.add(first);byte[] original="Original audio test".getBytes();try(OutputStream out=c.getContentResolver().openOutputStream(first,"wt")){assertNotNull(out);out.write(original);}Uri second=OndaFolders.create(c,"mp3",name);files.add(second);assertNotEquals(first,second);try(InputStream in=c.getContentResolver().openInputStream(first)){assertNotNull(in);ByteArrayOutputStream bytes=new ByteArrayOutputStream();byte[] buffer=new byte[1024];int n;while((n=in.read(buffer))!=-1)bytes.write(buffer,0,n);assertArrayEquals(original,bytes.toByteArray());}Uri video=OndaFolders.create(c,"mp4",name);files.add(video);assertTrue(DocumentsContract.getDocumentId(video).contains("Vídeos"));JSONObject report=new JSONObject().put("tree",tree.toString()).put("separateAudioVideo",true).put("existingFilePreserved",true);try(FileOutputStream out=new FileOutputStream(new File(c.getFilesDir(),"onda-folders-tests.json"))){out.write(report.toString().getBytes(java.nio.charset.StandardCharsets.UTF_8));}}finally{for(Uri file:files)try{DocumentsContract.deleteDocument(c.getContentResolver(),file);}catch(Exception ignored){}SharedPreferences.Editor edit=prefs.edit().clear();for(Map.Entry<String,?> item:old.entrySet())if(item.getValue() instanceof String)edit.putString(item.getKey(),(String)item.getValue());else if(item.getValue() instanceof Boolean)edit.putBoolean(item.getKey(),(Boolean)item.getValue());edit.commit();}}
 @Test public void cleanupUiFixture()throws Exception{if(previous!=null)c.getSharedPreferences(DownloadHistory.PREF,0).edit().putString("data",previous).commit();for(DownloadHistory.Entry entry:DownloadHistory.read(c))if(entry.source.equals("https://raw.githubusercontent.com/cristianoarakaki-cpu/Arakaki/245b693e64cf5b5b33bc2a5f491a607f6a435655/Onda/tests/fixtures/download.mp4")&&entry.uri.startsWith("content://"))try{DocumentsContract.deleteDocument(c.getContentResolver(),Uri.parse(entry.uri));}catch(Exception ignored){}}
}
